parameters.jsCode:
// 오행 테마 풀 — 날짜에 따라 매일 하나씩 자동 선택 (영어 부제 적용)
const themes = [
  { k: 'Quiet Wandering', ke: 'A day to drift and reflect', b: 'Today carries the mood of a quiet wandering. Let your steps be slow and your mind stay open.' },
  { k: 'Rising Fire', ke: 'Bold energy is on your side', b: 'Your Fire element burns bright today. Channel it into one bold move you have been postponing.' },
  { k: 'Still Water', ke: 'Clarity comes from calm', b: 'Still Water energy. Reflect before you react, and clarity will rise to the surface.' },
  { k: 'Deep Roots', ke: 'Strength in what you have built', b: 'Earth grounds you today. Tend patiently to what you have already built.' },
  { k: 'Sharp Metal', ke: 'Focus, then let go', b: 'Metal sharpens your focus. Cut away one thing that no longer serves you.' },
  { k: 'Green Sprout', ke: 'Small starts, big growth', b: 'Wood energy of new growth. A small start today becomes tomorrow\u2019s strength.' },
  { k: 'Golden Hour', ke: 'A lucky window opens', b: 'A lucky window opens this afternoon. Say yes to the unexpected and see where it leads.' }
];
const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const dayOfYear = Math.floor((now - start) / 86400000);
const t = themes[dayOfYear % themes.length];
const base = 'https://k-saju.me/api/og/keyword-card';
const cardUrl = base + '?fmt=square&k=' + encodeURIComponent(t.k) + '&ke=' + encodeURIComponent(t.ke) + '&b=' + encodeURIComponent(t.b);
const hashtags = '#ksaju #ksajume #saju #koreanastrology #fourpillars #easternastrology #dailysaju #kpop #spirituality #astrology #selfcare';
const caption = '🔮 Your daily Korean Saju: ' + t.k + '\n\n' + t.b + '\n\nWhich element are you? Get your free daily Saju card → k-saju.me\n\n' + hashtags;
return [{ json: { keyword: t.k, keywordEn: t.ke, body: t.b, caption, hashtags, cardUrl } }];

